from solution import pairs_sum_to_zero
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference(l):
    for i in range(len(l)):
        for j in range(i + 1, len(l)):
            if l[i] + l[j] == 0:
                return True
    return False


# --- concrete spec examples ---
def test_spec_example_1_3_5_0_is_false():
    assert pairs_sum_to_zero([1, 3, 5, 0]) is False


def test_spec_example_1_3_neg2_1_is_false():
    assert pairs_sum_to_zero([1, 3, -2, 1]) is False


def test_spec_example_1_2_3_7_is_false():
    assert pairs_sum_to_zero([1, 2, 3, 7]) is False


def test_spec_example_2_4_neg5_3_5_7_is_true():
    assert pairs_sum_to_zero([2, 4, -5, 3, 5, 7]) is True


def test_spec_example_singleton_is_false():
    assert pairs_sum_to_zero([1]) is False


# --- zero handling: distinct positions vs distinct values ---
def test_property_two_zeros_sum_to_zero():
    assert pairs_sum_to_zero([0, 0]) is True


def test_property_single_zero_is_false():
    assert pairs_sum_to_zero([0]) is False


def test_property_three_zeros_is_true():
    assert pairs_sum_to_zero([0, 0, 0]) is True


def test_property_zero_pair_among_others_is_true():
    assert pairs_sum_to_zero([1, 0, 2, 0]) is True


def test_property_lone_zero_among_nonpairs_is_false():
    assert pairs_sum_to_zero([1, 3, 5, 0]) is False
    assert pairs_sum_to_zero([0, 1, 2, 3]) is False


def test_property_empty_list_is_false():
    assert pairs_sum_to_zero([]) is False


def test_property_singleton_lists_are_false():
    assert pairs_sum_to_zero([5]) is False
    assert pairs_sum_to_zero([-7]) is False
    assert pairs_sum_to_zero([0]) is False


def test_property_duplicate_nonzero_without_negation_is_false():
    assert pairs_sum_to_zero([5, 5]) is False
    assert pairs_sum_to_zero([2, 2, 2]) is False


def test_property_simple_negation_pair_is_true():
    assert pairs_sum_to_zero([2, -2]) is True
    assert pairs_sum_to_zero([-3, 1, 3]) is True
    assert pairs_sum_to_zero([5, -5, 5]) is True


# --- equivalence to obviously-correct reference model ---
@given(st.lists(st.integers(min_value=-10, max_value=10), min_size=0, max_size=8))
def test_property_matches_brute_force_reference(l):
    assert pairs_sum_to_zero(l) == reference(l)


@given(st.lists(st.integers(min_value=-5, max_value=5), min_size=0, max_size=6))
def test_property_matches_reference_with_zero_heavy_lists(l):
    # bias toward zeros to stress distinct-position semantics for 0+0==0
    assert pairs_sum_to_zero(l) == reference(l)


@given(
    st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=10),
    st.integers(min_value=-20, max_value=20),
)
def test_property_adding_negated_pair_forces_true(l, x):
    # metamorphic: appending both x and -x (two new distinct positions)
    # must yield True, since those two sum to zero
    extended = l + [x, -x]
    assert pairs_sum_to_zero(extended) is True


@given(st.lists(st.integers(min_value=-10, max_value=10), min_size=0, max_size=8))
def test_property_permutation_invariance(l):
    # result depends only on multiset of values, not order
    import random
    perm = list(l)
    # deterministic permutation: reverse
    assert pairs_sum_to_zero(perm[::-1]) == reference(l) == pairs_sum_to_zero(l)


@given(st.lists(st.integers(min_value=1, max_value=20), min_size=0, max_size=8))
def test_property_all_positive_nonzero_is_false(l):
    # strictly positive ints can never sum to zero
    assert pairs_sum_to_zero(l) is False


@given(st.lists(st.integers(min_value=-20, max_value=-1), min_size=0, max_size=8))
def test_property_all_negative_is_false(l):
    assert pairs_sum_to_zero(l) is False


@given(st.lists(st.integers(min_value=-10, max_value=10), min_size=0, max_size=8))
def test_property_true_implies_witness_pair_exists(l):
    result = pairs_sum_to_zero(l)
    witness = any(
        l[i] + l[j] == 0 for i in range(len(l)) for j in range(i + 1, len(l))
    )
    assert result == witness
    if result is True:
        assert witness is True
    else:
        assert witness is False


def test_property_return_type_is_bool():
    assert pairs_sum_to_zero([2, -2]) is True
    assert pairs_sum_to_zero([1, 2]) is False
    assert type(pairs_sum_to_zero([2, -2])) is bool
    assert type(pairs_sum_to_zero([1, 2])) is bool
